var ScalesPage={elems:{}};ScalesPage.preInit=function(){$('#submit_button_con').addClass('hidden');$('#op_submit_button_con').addClass('hidden');$('#page_content_con').find("form").on('submit',function(e){e.preventDefault(e)})};ScalesPage.init=function(){Scale.init();Chord.init();this.setElems();this.bindAll();this.bindChordButtons();this.setScaleFromForm();InstrumentOptions.init();PageMeta.init();if(instrumentInfo.code=='piano'){KeyPositionPiano.init()}console.log('Scale Page Initialized')};ScalesPage.setElems=function(){var scale_chord_table=$("#scale_chord_table");this.elems={note:$("#note"),scale:$("#scale"),directions_con:$("#directions_con"),scale_info_con:$("#scale_info_con"),chord_list_con:$("#chord_list_con"),info_scale_name:$("#info_scale_name"),info_scale_notes:$("#info_scale_notes"),info_scale_degrees:$("#info_scale_degrees"),info_scale_steps:$("#info_scale_steps"),info_scale_semitones:$("#info_scale_semitones"),info_scale_name_alt_label:$("#info_scale_name_alt_label"),info_scale_name_alt:$("#info_scale_name_alt"),info_chord_name:$("#info_chord_name"),info_chord_notes:$("#info_chord_notes"),info_chord_degrees:$("#info_chord_degrees"),info_chord_abbrev:$("#info_chord_abbrev"),info_chord_name_alt_label:$("#info_chord_name_alt_label"),info_chord_name_alt:$("#info_chord_name_alt"),chord_info:$("#chord_info"),scale_chord_table_head_row:scale_chord_table.find('thead tr'),scale_chord_table_body:scale_chord_table.find('tbody')};if(instrumentInfo.code=='no_instrument'){this.elems.scale_info_main=$("#scale_info_main");this.elems.scale_name=$("#scale_name");this.elems.scale_notes=$("#scale_notes");this.elems.chord_info_main=$("#chord_info_main");this.elems.chord_name=$("#chord_name");this.elems.chord_notes=$("#chord_notes");this.elems.no_notes_selected=$("#no_notes_selected")}};ScalesPage.bindAll=function(){this.elems.note.on("change",function(){ScalesPage.formUpdated()});this.elems.scale.on("change",function(){ScalesPage.formUpdated()})};ScalesPage.formUpdated=function(){this.setScaleFromForm();if(Scale.isScaleSet){this.updateScaleDisplay()}else{this.clearScaleDisplay()}if(InstrumentOptions.isStringed){ScalesStringed.updateDisplay('scale')}else if(instrumentInfo.code=='piano'){KeyPositionPiano.update(Scale.scaleNoteKeyAr,'scale')}PageMeta.update()};ScalesPage.setScaleFromForm=function(){Scale.setNoteByCode(this.elems.note.val());Scale.setScaleByCode(this.elems.scale.val());Scale.load()};ScalesPage.updateScaleDisplay=function(){var s=allScaleAr[Scale.scaleKey];var noteStr='';var sep='';var x;this.elems.scale_info_con.removeClass('hidden');this.elems.chord_list_con.removeClass('hidden');this.elems.directions_con.addClass('hidden');for(x=0;x<Scale.scaleNoteKeyAr.length;x++){noteStr+=sep+Note.getNote(Scale.scaleNoteKeyAr[x]);sep=', '}var scaleFullName=Note.getNote(Scale.noteKey)+' '+s[2];this.elems.info_scale_name.html(scaleFullName);this.elems.info_scale_notes.html(noteStr);this.elems.info_scale_degrees.html(s[4]);this.elems.info_scale_steps.html(s[6]);this.elems.info_scale_semitones.html(s[5]);if(s[3].length>0){this.elems.info_scale_name_alt_label.removeClass('hidden');this.elems.info_scale_name_alt.html(s[3]).removeClass('hidden')}else{this.elems.info_scale_name_alt_label.addClass('hidden');this.elems.info_scale_name_alt.html('').addClass('hidden')}this.elems.scale_info_con.removeClass('hidden');this.elems.chord_list_con.removeClass('hidden');this.elems.directions_con.addClass('hidden');if(instrumentInfo.code=='no_instrument'){this.elems.scale_info_main.removeClass('hidden');this.elems.scale_name.html(scaleFullName);this.elems.scale_notes.html(noteStr);this.elems.no_notes_selected.addClass('hidden');this.elems.chord_info_main.removeClass('hidden')}this.loadChordTable();this.clearChordDisplay();console.log('Scale Loaded: '+Note.getNote(Scale.noteKey,'url').toUpperCase()+' '+s[2])};ScalesPage.loadChordTable=function(){this.elems.scale_chord_table_body.find('button').off();var htmlStr='';var x,y,chordName,chordLink,moreButton;for(x=0;x<Scale.scaleNoteKeyAr.length;x++){htmlStr+='<th>'+Note.getNote(Scale.scaleNoteKeyAr[x])+'</th>'}this.elems.scale_chord_table_head_row.html(htmlStr);htmlStr='';for(x=0;x<Chord.allChordLength;x++){htmlStr+='<tr class="scale_chord_tr">';for(y=0;y<Scale.scaleNoteKeyAr.length;y++){chordName=Note.getNote(Scale.scaleNoteKeyAr[y])+allChordAr[x][4];chordLink=Note.getNote(Scale.scaleNoteKeyAr[y],'url')+'-'+allChordAr[x][0];moreButton='';if(this.isChordInScale(Scale.scaleNoteKeyAr[y],x)){}else{moreButton+=' disabled="disabled"'}if(allChordAr[x][4].replace('&flat;','x').replace('&sharp;','x').length>=5){moreButton+=' class="small"'}htmlStr+='<td>'+'<button name="chord" value="'+chordLink+'"'+moreButton+'>'+chordName+'</button>'+'</td>'}htmlStr+='</tr>'}this.elems.scale_chord_table_body.html(htmlStr);this.bindChordButtons()};ScalesPage.bindChordButtons=function(){this.elems.scale_chord_table_body.find('button').on("click",function(event){event.preventDefault();ScalesPage.setChord($(this));ScalesPage.displayChord();if(InstrumentOptions.isStringed){ScalesStringed.updateDisplay('chord')}})};ScalesPage.clearChordDisplay=function(elem){Chord.noteKey=-1;Chord.chordKey=-1;this.elems.info_chord_name.html('Select A Chord');this.elems.chord_info.addClass('hidden');this.elems.info_chord_notes.html('');this.elems.info_chord_degrees.html('');this.elems.info_chord_abbrev.html('');this.elems.info_chord_name_alt_label.addClass('hidden');this.elems.info_chord_name_alt.html('').addClass('hidden');if(instrumentInfo.code=='no_instrument'){this.elems.chord_info_main.addClass('hidden');this.elems.chord_name.addClass('');this.elems.chord_notes.addClass('')}};ScalesPage.displayChord=function(elem){if(Chord.noteKey<0||Chord.chordKey<0){this.clearChordDisplay();return}var c=allChordAr[Chord.chordKey];var noteStr='';var sep='';var x;for(x=0;x<c[1].length;x++){noteStr+=sep+Note.getNote(c[1][x]+Chord.noteKey);sep=', '}var abbrevStr=c[4];if(c[5].length>1){abbrevStr+=', '+c[5]}var chordFullName=Note.getNote(Chord.noteKey)+' '+c[2];this.elems.info_chord_name.html(chordFullName);this.elems.info_chord_notes.html(noteStr);this.elems.info_chord_degrees.html(c[3]);this.elems.info_chord_abbrev.html(abbrevStr);if(c[6].length>0){this.elems.info_chord_name_alt_label.removeClass('hidden');this.elems.info_chord_name_alt.html(c[6]).removeClass('hidden')}else{this.elems.info_chord_name_alt_label.addClass('hidden');this.elems.info_chord_name_alt.html('').addClass('hidden')}this.elems.chord_info.removeClass('hidden');if(instrumentInfo.code=='no_instrument'){this.elems.chord_name.html(chordFullName);this.elems.chord_notes.html(noteStr);this.elems.chord_info_main.removeClass('hidden')}if(instrumentInfo.code=='piano'){KeyPositionPiano.update(Chord.chordNoteKeyAr,'chord')}console.log('Chord Loaded: '+Note.getNote(Chord.noteKey,'url').toUpperCase()+' '+c[2])};ScalesPage.setChord=function(elem){if(elem.prop("disabled")===true){return}var note,chordCode,val;val=elem.val();if(val.substr(1,7)=='-sharp-'){note=val.substr(0,7);chordCode=val.substr(8)}else{note=val.substr(0,1);chordCode=val.substr(2)}Chord.setNoteByCode(note);Chord.setChordByCode(chordCode);Chord.load()};ScalesPage.isChordInScale=function(noteKey,chordKey){var x,nk;for(x=0;x<allChordAr[chordKey][1].length;x++){nk=(allChordAr[chordKey][1][x]+noteKey)%Note.allNoteCount;if(Scale.scaleNoteKeyAr.indexOf(nk)<0){return false}}return true};ScalesPage.clearScaleDisplay=function(){this.elems.scale_info_con.addClass('hidden');this.elems.chord_list_con.addClass('hidden');this.elems.directions_con.removeClass('hidden');this.elems.info_chord_name.html('Select A Scale');this.elems.info_scale_name.html('');this.elems.info_scale_notes.html('');this.elems.info_scale_degrees.html('');this.elems.info_scale_steps.html('');this.elems.info_scale_semitones.html('');this.elems.info_scale_name_alt_label.addClass('hidden');this.elems.info_scale_name_alt.html('').addClass('hidden');ScalesPage.clearChordDisplay();this.elems.scale_chord_table_body.find('button').off();this.elems.scale_chord_table_head_row.empty();this.elems.scale_chord_table_body.empty()};ScalesPage.preInit();$(document).ready(function(){ScalesPage.init()});